from pathlib import Path
import json,zipfile
from PIL import Image
variants=json.loads(Path('docs/evidence/candle-logo/variants.json').read_text())
root=Path('frontend/public/concepts')
for v in variants:
 d=root/'candle-logo'/f'v{v["number"]}'
 Image.open(d/'favicon-48.png').save(d/'favicon.ico',format='ICO',sizes=[(16,16),(32,32),(48,48)],append_images=[Image.open(d/'favicon-16.png'),Image.open(d/'favicon-32.png')])
 with zipfile.ZipFile(d/'assets.zip','w',zipfile.ZIP_DEFLATED) as z:
  for p in sorted(d.iterdir()):
   if p.suffix in ['.svg','.png','.ico']:z.write(p,p.name)
  for name in ['fraunces','manrope']:z.write(root/'logo-ideas'/(name+'-OFL.txt'),name+'-OFL.txt')
css='''@font-face{font-family:Fraunces;src:url('logo-ideas/fraunces.woff2');font-weight:100 900;font-display:swap}@font-face{font-family:Manrope;src:url('logo-ideas/manrope.woff2');font-weight:200 800;font-display:swap}*{box-sizing:border-box}body{margin:0;color:#291c20;background:#fff;font:16px/1.6 Manrope,Arial,sans-serif}h1,h2,h3{font-family:Fraunces,Georgia,serif;line-height:1.15}h1{font-size:46px;letter-spacing:-.03em;margin:0 0 18px}h2{font-size:30px;margin:0 0 12px}h3{font-size:22px;margin:0 0 16px}p{margin:0 0 20px}a{color:inherit;text-underline-offset:4px;display:inline-flex;align-items:center;min-height:44px}a:focus-visible{outline:3px solid #0f6b4f;outline-offset:4px}header,main,footer{max-width:1360px;margin:auto;padding:40px 48px}header p{max-width:760px}nav{display:flex;flex-wrap:wrap;gap:12px}nav a{padding:8px 18px;border:1px solid #d6c8cc;font-weight:700;text-decoration:none}.overview{display:grid;grid-template-columns:repeat(4,1fr);gap:16px;margin-top:24px}.overview a{display:flex;flex-direction:column;align-items:stretch;padding:16px;background:#a3122f;color:#fff;font-size:14px;text-decoration:none}.overview img{width:100%;height:80px;object-fit:contain}.overview span{margin-top:8px}main{padding-top:0}article{border-top:2px solid #291c20;padding:28px 0 48px}.intro{display:flex;gap:24px;margin-bottom:24px}.num{font:500 36px Fraunces;min-width:42px}.intro p{max-width:720px;margin:0}.marks{display:grid;grid-template-columns:1fr 1fr}.mark{padding:30px 32px;min-height:185px;display:flex;flex-direction:column;justify-content:center;gap:12px}.mark img{width:100%;height:115px;object-fit:contain}.red{background:#a3122f;color:white}.white{border:1px solid #e4d9dc}.caption{font-size:13px}.details{display:grid;grid-template-columns:1.6fr 1fr;gap:48px;margin-top:32px}.header-preview{padding:14px 22px;min-height:76px;display:flex;align-items:center;justify-content:space-between;gap:20px;margin-bottom:12px}.header-preview img{width:156px;height:auto}.header-preview span{font-size:14px}.exports{display:flex;align-items:end;gap:24px;flex-wrap:wrap;margin:24px 0}.exports figure{margin:0;text-align:center}.exports img{display:block;margin:auto auto 10px}.exports figcaption{font-size:13px}.phone-area{display:flex;flex-direction:column;align-items:center}.phone{border:5px solid #291c20;border-radius:32px;width:240px;min-height:350px;padding:14px 18px 20px;background:#f1e7e9;color:#291c20}.phone-top{display:flex;justify-content:space-between;font-size:13px;font-weight:700}.island{width:72px;height:20px;background:#291c20;border-radius:20px}.phone-apps{display:grid;grid-template-columns:1fr 1fr;gap:26px 18px;padding-top:40px}.phone-apps>div{text-align:center;font-size:13px}.phone-apps img{width:60px;height:60px;border-radius:14px;display:block;margin:0 auto 8px}.dummy{height:60px;width:60px;border-radius:14px;background:#fff;display:grid;place-items:center;margin:0 auto 8px;color:#59474e;font-size:23px}.home-line{height:4px;background:#291c20;border-radius:4px;width:90px;margin:38px auto 0}.phone-area>p{font-size:13px;margin-top:12px}.downloads{display:flex;flex-wrap:wrap;gap:12px 24px;border-top:1px solid #e4d9dc;padding-top:16px;margin-top:24px;font-size:14px}.downloads a:first-child{background:#0f6b4f;color:white;padding:8px 18px;text-decoration:none}footer{padding-top:0;font-size:14px}footer p{max-width:900px}@media(max-width:900px){header,main,footer{padding-left:24px;padding-right:24px}.overview{grid-template-columns:1fr 1fr}.details{gap:24px;grid-template-columns:1.3fr 1fr}.mark{padding:20px}.header-preview{padding:12px}.header-preview span{display:none}}@media(max-width:600px){header,main,footer{padding-left:16px;padding-right:16px}header{padding-top:28px}h1{font-size:36px}.overview{gap:10px}.overview a{padding:10px}.overview img{height:56px}.intro{gap:12px}.num{min-width:32px;font-size:30px}h2{font-size:28px}.marks,.details{grid-template-columns:1fr}.mark{padding:22px;min-height:145px}.mark img{height:90px}.details{gap:30px}.exports{gap:20px}.header-preview span{display:block}.phone-area{align-items:flex-start}.phone{width:240px}.intro p{font-size:15px}.downloads{gap:8px 20px}article{padding-bottom:36px}}'''
rows=[]
for v in variants:
 i=v['number'];base=f'candle-logo/v{i}/'
 rows.append(f'''<article id="v{i}"><div class="intro"><span class="num">0{i}</span><div><h2>{v['name']}</h2><p>{v['rationale']}</p></div></div><div class="marks"><div class="mark red"><img src="{base}wordmark-white.svg" alt="Wisher.az candle wordmark, variant {i}, on red"><span class="caption">Reversed on pomegranate</span></div><div class="mark white"><img src="{base}wordmark-red.svg" alt="Wisher.az candle wordmark, variant {i}, on white"><span class="caption">On white</span></div></div><div class="details"><div><h3>At header size</h3><div class="header-preview red"><img src="{base}wordmark-white.svg" alt="Wisher.az header logo"><span>Header preview</span></div><div class="header-preview white"><img src="{base}wordmark-red.svg" alt="Wisher.az header logo on white"><span>156 px wide</span></div><div class="exports">'''+''.join(f'<figure><img src="{base}{file}" width="{size}" height="{size}" alt="{label}"><figcaption>{label}</figcaption></figure>' for size,file,label in [(16,'favicon-16.png','16 px'),(32,'favicon-32.png','32 px'),(48,'favicon-48.png','48 px'),(96,'app-icon-1024.png','App icon')])+f'''</div><p class="caption">The 16 px drawing has a wider stem, a clear flame gap and no wick. The app and Apple icons are opaque, square exports; the device supplies the rounded mask.</p></div><div class="phone-area"><div class="phone" role="img" aria-label="Illustrative phone home screen with variant {i} Wisher icon"><div class="phone-top"><span>9:41</span><span class="island"></span><span>100%</span></div><div class="phone-apps"><div><img src="{base}app-icon-1024.png" alt=""><span>Wisher</span></div><div><span class="dummy">12</span><span>Calendar</span></div><div><span class="dummy">Aa</span><span>Notes</span></div><div><span class="dummy">09</span><span>Clock</span></div></div><div class="home-line"></div></div><p>Illustrative home-screen mockup</p></div></div><div class="downloads"><a href="{base}assets.zip" download>Download variant {i}</a><a href="{base}wordmark-red.svg" download>Wordmark SVG</a><a href="{base}app-icon-1024.png" download>1024 PNG</a><a href="{base}apple-touch-icon.png" download>Apple touch icon</a><a href="{base}favicon.svg" download>SVG favicon</a><a href="{base}favicon.ico" download>ICO favicon</a></div></article>''')
html='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Wisher - Candle-i logo study</title><style>'''+css+'''</style></head><body><header><h1>A candle inside<br>the Wisher name.</h1><p>Four refinements of Rashad's candle-i idea. Compare the lettering, then the header-size mark and its matching icon. Every wordmark, including .az, is drawn as vector paths.</p><nav aria-label="Variants">'''+''.join(f'<a href="#v{i}">0{i}</a>' for i in range(1,5))+'''</nav><div class="overview">'''+''.join(f'<a href="#v{v["number"]}"><img src="candle-logo/v{v["number"]}/wordmark-white.svg" alt=""><span>0{v["number"]} / {v["name"]}</span></a>' for v in variants)+'''</div></header><main>'''+''.join(rows)+'''</main><footer><p>Review only. Nothing has been installed into the site. No variant is selected. All four treatments use flat color without glow. The lettering is outlined from licensed Fraunces and Manrope, with custom candle shapes and adjusted spacing.</p></footer></body></html>'''
(root/'candle-logo.html').write_text(html)
